  ];

  // Regex to split by keys
  // Build a regex matching any of these keys followed by :
  const keyPattern = new RegExp(`(${keys.map(k => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')})\\s*:`, 'g');

