function isValid(str) {
  if (!str) return false;
  str = str.trim();
  if (str === '' || str === '-' || str === '*' || str === '.' || str === '폐업') return false;
  if (str.includes('*')) return false; // reject masked data
  return true;
}

function cleanVal(str) {
  if (!str) return '';
  str = str.trim();
  if (str === '-' || str === '*' || str === '.') return '';
  if (str.includes('*')) return ''; // reject masked data
  return str;
}

function cleanPhone(str) {
  if (!str) return '';
  let cleaned = str.replace(/\(※[^\)]*\)/g, '').replace(/[^0-9\-~,\s]/g, '').trim();
  if (cleaned.includes('*') || cleaned === '-' || cleaned === '.' || cleaned.length < 7) return '';
  return cleaned;
}

function cleanEmpCount(str) {
  if (!str) return '';
  if (str.includes('*') || str === '-') return '';
  str = str.replace(/명/g, '').trim();
  return str;
}

function cleanUrl(str) {
  if (!str) return '';
  if (str === '-' || str.includes('*')) return '';
  let url = str.trim();
  if (!url.startsWith('http://') && !url.startsWith('https://')) {
    url = 'http://' + url;
  }
  return url;
}

function cleanAddr(addr) {
  if (!addr || addr.includes('*') || addr === '-') return '';
  // sometimes Bizno appends english address or lot address
  // e.g. "경상북도 구미시 신시로 80-1 (송정동)"
