  cleaned = cleaned.replace(/\s+[0-9]+(-[0-9]+)?,\s+[A-Za-z0-9\-,\s]+Korea.*$/i, '');
  cleaned = cleaned.replace(/\s+[0-9]+(-[0-9]+)?,\s+[A-Za-z0-9\-,\s]+beon-gil.*$/i, '');
