() => {
  const cards = document.querySelectorAll('.company-list-item, .search-card, li, .card');
  const results = [];
  document.querySelectorAll('li, div').forEach(el => {
    if (el.innerText && el.innerText.includes('산업명') && el.innerText.includes('대표자명') && el.innerText.length < 500) {
      results.push(el.innerText);
    }
  });
  return results;
}

async () => {
  await new Promise(r => setTimeout(r, 1000));
  const text = document.body.innerText;
  const match = text.match(/산업명\s*\n\s*([^\n]+)/);
  const repMatch = text.match(/대표자명\s*\n\s*([^\n]+)/);
  return {
    industry: match ? match[1].trim() : null,
    representative: repMatch ? repMatch[1].trim() : null,
    snippet: text.slice(0, 1500)
  };
}

