  out[0] = '배현명';

  if (biz) {
    const t = biz.tableFields || {};
    const s = biz.summaryFields || {};
    const ind = biz.industryNts || {};

    // Column 1: 상태 (폐업 여부)
    const bizStatus = s['사업자 현재 상태(※국세청 홈택스 실시간 정보제공)'] || t['사업자 현재 상태'] || '';
    if (bizStatus.includes('폐업') || niceItem?.ipodivcd === '92') {
