function escapeCsvCol(val) {
  if (val === null || val === undefined) val = '';
  val = String(val).trim();
  if (val.includes(',') || val.includes('"') || val.includes('\n') || val.includes('\r')) {
    return '"' + val.replace(/"/g, '""') + '"';
  }
  return val;
}

